    {
      "action_name": "auto-prepare",
      "description": "初始化SPIDR板卡通信并准备使用。",
      "description_en": "Initialize communication with the SPIDR board and prepare it for use."
    },
    {
      "action_name": "auto-resetModule",
      "description": "复位SPIDR模块并设置读出速度。",
      "description_en": "Reset the SPIDR module and set the readout speed."
    },
    {
      "action_name": "auto-CpuToTpx",
      "description": "读取或写入CPU到Timepix的寄存器访问值。",
      "description_en": "Read or write the CPU-to-Timepix register access value."
    },
    {
      "action_name": "auto-ShutterTriggerCtrl",
      "description": "读取或写入快门触发控制寄存器。",
      "description_en": "Read or write the shutter trigger control register."
    },
    {
      "action_name": "auto-ShutterTriggerMode",
      "description": "读取或设置快门触发模式。",
      "description_en": "Get or set the shutter trigger mode."
    },
    {
      "action_name": "auto-ShutterTriggerCount",
      "description": "读取或设置自动触发模式下的快门触发次数。",
      "description_en": "Get or set the shutter trigger count in auto-trigger mode."
    },
    {
      "action_name": "auto-ShutterTriggerFreq",
      "description": "读取或设置自动触发频率。",
      "description_en": "Get or set the auto-trigger frequency."
    },
    {
      "action_name": "auto-ShutterTriggerLength",
      "description": "读取或设置每次触发的快门开启时长。",
      "description_en": "Get or set the shutter open duration for each trigger."
    },
    {
      "action_name": "auto-ShutterTriggerDelay",
      "description": "读取或设置自动触发模式下的再次触发延迟。",
      "description_en": "Get or set the retrigger delay in auto-trigger mode."
    },
    {
      "action_name": "auto-DeviceAndPorts",
      "description": "读取已连接设备及端口信息。",
      "description_en": "Get connected device and port information."
    },
    {
      "action_name": "auto-TdcTriggerCounter",
      "description": "读取TDC触发计数。",
      "description_en": "Get the TDC trigger count."
    },
    {
      "action_name": "auto-UdpPacketCounter",
      "description": "读取或设置UDP数据包计数器。",
      "description_en": "Get or set the UDP packet counter."
    },
    {
      "action_name": "auto-UdpMonPacketCounter",
      "description": "读取或设置UDP监测数据包计数器。",
      "description_en": "Get or set the UDP monitor packet counter."
    },
    {
      "action_name": "auto-UdpPausePacketCounter",
      "description": "读取或设置读出暂停期间的UDP数据包计数器。",
      "description_en": "Get or set the UDP packet counter accumulated during readout pause."
    },
    {
      "action_name": "auto-softwareVersion",
      "description": "读取SPIDR板卡软件版本。",
      "description_en": "Get the SPIDR board software version."
    },
    {
      "action_name": "auto-firmwareVersion",
      "description": "读取FPGA固件版本。",
      "description_en": "Get the FPGA firmware version."
    },
    {
      "action_name": "auto-localTemperature",
      "description": "读取本地温度传感器温度。",
      "description_en": "Get the local temperature sensor reading."
    },
    {
      "action_name": "auto-remoteTemperature",
      "description": "读取远端温度传感器温度。",
      "description_en": "Get the remote temperature sensor reading."
    },
    {
      "action_name": "auto-fpgaTemperature",
      "description": "读取FPGA板温度。",
      "description_en": "Get the FPGA board temperature."
    },
    {
      "action_name": "auto-humidity",
      "description": "读取湿度。",
      "description_en": "Get the humidity."
    },
    {
      "action_name": "auto-pressure",
      "description": "读取压力。",
      "description_en": "Get the pressure."
    },
    {
      "action_name": "auto-chipboardFanSpeed",
      "description": "读取芯片板风扇转速。",
      "description_en": "Get the chipboard fan speed."
    },
    {
      "action_name": "auto-boardFanSpeed",
      "description": "读取板卡风扇转速。",
      "description_en": "Get the board fan speed."
    },
    {
      "action_name": "auto-avdd",
      "description": "读取AVDD电压。",
      "description_en": "Get the AVDD voltage."
    },
    {
      "action_name": "auto-vdd",
      "description": "读取VDD电压。",
      "description_en": "Get the VDD voltage."
    },
    {
      "action_name": "auto-dvdd",
      "description": "读取DVDD电压。",
      "description_en": "Get the DVDD voltage."
    },
    {
      "action_name": "auto-avddNow",
      "description": "读取当前AVDD电压。",
      "description_en": "Get the current AVDD voltage."
    },
    {
      "action_name": "auto-vddNow",
      "description": "读取当前VDD电压。",
      "description_en": "Get the current VDD voltage."
    },
    {
      "action_name": "auto-dvddNow",
      "description": "读取当前DVDD电压。",
      "description_en": "Get the current DVDD voltage."
    },
    {
      "action_name": "auto-deviceCount",
      "description": "读取已连接设备数量。",
      "description_en": "Get the number of connected devices."
    },
    {
      "action_name": "auto-deviceIds",
      "description": "读取已连接设备ID列表。",
      "description_en": "Get the IDs of connected devices."
    },
    {
      "action_name": "auto-linkCounts",
      "description": "读取链路计数信息。",
      "description_en": "Get link count information."
    },
    {
      "action_name": "auto-chipboardId",
      "description": "读取芯片板ID。",
      "description_en": "Get the chipboard ID."
    },
    {
      "action_name": "auto-setBusy",
      "description": "设置忙状态。",
      "description_en": "Set the busy state."
    },
    {
      "action_name": "auto-clearBusy",
      "description": "清除忙状态。",
      "description_en": "Clear the busy state."
    },
    {
      "action_name": "auto-resetDevices",
      "description": "复位所有已连接设备。",
      "description_en": "Reset all connected devices."
    },
    {
      "action_name": "auto-reinitDevices",
      "description": "复位并重新初始化所有设备。",
      "description_en": "Reset and reinitialize all devices."
    },
    {
      "action_name": "auto-setPowerPulseEnable",
      "description": "启用或禁用电源脉冲功能。",
      "description_en": "Enable or disable power pulsing."
    },
    {
      "action_name": "auto-setTpxPowerPulseEnable",
      "description": "启用或禁用Timepix电源脉冲功能。",
      "description_en": "Enable or disable Timepix power pulsing."
    },
    {
      "action_name": "auto-setBiasSupplyEnable",
      "description": "启用或禁用偏压电源。",
      "description_en": "Enable or disable the bias supply."
    },
    {
      "action_name": "auto-biasVoltage",
      "description": "读取或设置偏压电压。",
      "description_en": "Get or set the bias voltage."
    },
    {
      "action_name": "auto-enableDecoders",
      "description": "启用或禁用内部解码器以处理ToA值。",
      "description_en": "Enable or disable the internal decoders for ToA values."
    },
    {
      "action_name": "auto-enablePeriphClk80Mhz",
      "description": "启用80 MHz外设时钟。",
      "description_en": "Enable the 80 MHz peripheral clock."
    },
    {
      "action_name": "auto-disablePeriphClk80Mhz",
      "description": "禁用80 MHz外设时钟。",
      "description_en": "Disable the 80 MHz peripheral clock."
    },
    {
      "action_name": "auto-enableExternalRefClock",
      "description": "启用外部参考时钟。",
      "description_en": "Enable the external reference clock."
    },
    {
      "action_name": "auto-disableExternalRefClock",
      "description": "禁用外部参考时钟并使用内部参考时钟。",
      "description_en": "Disable the external reference clock and use the internal reference clock."
    },
    {
      "action_name": "auto-sequentialReadout",
      "description": "设置顺序读出模式参数。",
      "description_en": "Configure sequential readout mode parameters."
    },
    {
      "action_name": "auto-datadrivenReadout",
      "description": "切换到数据驱动读出模式。",
      "description_en": "Set the board to data-driven readout mode."
    },
    {
      "action_name": "auto-pauseReadout",
      "description": "暂停读出。",
      "description_en": "Pause readout."
    },
