      "action_name": "auto-setShutterTriggerConfig",
      "description": "一次性设置快门触发配置。",
      "description_en": "Set the shutter trigger configuration in one operation."
    },
    {
      "action_name": "auto-shutterTriggerConfig",
      "description": "读取快门触发配置。",
      "description_en": "Get the shutter trigger configuration."
    },
    {
      "action_name": "auto-startAutoTrigger",
      "description": "启动自动触发。",
      "description_en": "Start auto triggering."
    },
    {
      "action_name": "auto-stopAutoTrigger",
      "description": "停止自动触发。",
      "description_en": "Stop auto triggering."
    },
