      "action_name": "auto-openShutter",
      "description": "立即打开快门并保持开启。",
      "description_en": "Open the shutter immediately and keep it open."
    },
    {
      "action_name": "auto-closeShutter",
      "description": "立即关闭快门。",
      "description_en": "Close the shutter immediately."
    },
    {
      "action_name": "auto-externalShutterCounter",
      "description": "读取外部快门计数。",
      "description_en": "Get the external shutter count."
    },
    {
      "action_name": "auto-shutterCounter",
      "description": "读取快门计数。",
      "description_en": "Get the shutter count."
    },
