      "action_name": "auto-resetCounters",
      "description": "复位各类计数器。",
      "description_en": "Reset counters."
    },
    {
      "action_name": "auto-resetTimers",
      "description": "将所有定时器清零。",
      "description_en": "Reset all timers to zero."
    },
    {
      "action_name": "auto-getAdc",
      "description": "读取指定通道的ADC采样值。",
      "description_en": "Get ADC samples from the selected channel."
    },
    {
      "action_name": "auto-resetPacketCounters",
      "description": "复位数据包计数器。",
      "description_en": "Reset packet counters."
    },
    {
      "action_name": "auto-getSpidrReg",
      "description": "读取SPIDR寄存器。",
      "description_en": "Read a SPIDR register."
    },
    {
      "action_name": "auto-setSpidrReg",
      "description": "写入SPIDR寄存器。",
      "description_en": "Write a SPIDR register."
    },
    {
      "action_name": "auto-request",
      "description": "发送底层命令并可选择接收回复。",
      "description_en": "Send a low-level command and optionally receive a reply."
    },
    {
      "action_name": "auto-convertNtohl",
      "description": "将网络字节序数据转换为主机字节序。",
      "description_en": "Convert data from network byte order to host byte order."
    },
    {
      "action_name": "auto-convertHtonl",
      "description": "将主机字节序数据转换为网络字节序。",
      "description_en": "Convert data from host byte order to network byte order."
    },
    {
      "action_name": "auto-requestGetInt",
      "description": "发送底层命令并读取整数回复。",
      "description_en": "Send a low-level command and read an integer reply."
    },
    {
      "action_name": "auto-requestGetInts",
      "description": "发送底层命令并读取多个整数回复。",
      "description_en": "Send a low-level command and read multiple integer replies."
    },
    {
      "action_name": "auto-requestGetBytes",
      "description": "发送底层命令并读取字节数据回复。",
      "description_en": "Send a low-level command and read a byte payload reply."
    },
    {
      "action_name": "auto-requestGetIntBytes",
      "description": "发送底层命令并读取整数及字节数据回复。",
      "description_en": "Send a low-level command and read an integer plus byte payload reply."
    },
    {
      "action_name": "auto-requestSetInt",
      "description": "发送携带整数参数的底层命令。",
      "description_en": "Send a low-level command with an integer payload."
    },
    {
      "action_name": "auto-requestSetInts",
      "description": "发送携带多个整数参数的底层命令。",
      "description_en": "Send a low-level command with multiple integer payloads."
    },
    {
      "action_name": "auto-requestSetIntBytes",
      "description": "发送携带整数和字节数据的底层命令。",
      "description_en": "Send a low-level command with an integer and byte payload."
    }
  ]
}

